"""Patch client TRIAGE-V1: bouton Triage + modal du triage board dans calib.html.

PREREQUIS: patch_assist_client.py applique d'abord.
Idempotent. Backup: tools/calib.html.bak_triage
"""
import shutil, sys

P = 'tools/calib.html'
s = open(P).read()
if 'TRIAGE-V1' in s:
    print('deja patche'); sys.exit(0)
shutil.copy(P, P + '.bak_triage')

old_btn = '<button class="btn" id="btn-suspicious" style="background:#1c1c26;color:#f59e0b;border:1px solid #f59e0b">⚠ Suspicious</button>'
assert old_btn in s, 'bouton Suspicious introuvable'
s = s.replace(old_btn, old_btn + '\n  <button class="btn" id="triage-btn" style="background:#1c1c26;color:#e74c3c;border:1px solid #e74c3c" title="Triage: cams categorisees avec action recommandee">Triage</button>', 1)

block = '<!-- [TRIAGE-V1] modal du triage board -->\n<div id="triage-modal" style="display:none;position:fixed;inset:0;background:#000a;z-index:100">\n <div style="position:absolute;top:5vh;left:50%;transform:translateX(-50%);width:min(860px,94vw);max-height:88vh;\n   overflow-y:auto;background:var(--surface,#16161c);border:1px solid var(--border,#2a2a33);border-radius:10px;padding:16px;\n   font-family:var(--mono,monospace);font-size:12px">\n  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">\n    <b style="color:#f59e0b;font-size:14px">Triage board</b>\n    <span id="triage-count" style="color:var(--mid,#888)"></span>\n    <button onclick="document.getElementById(\'triage-modal\').style.display=\'none\'"\n      style="background:none;border:1px solid var(--border,#333);color:var(--mid,#aaa);border-radius:5px;padding:3px 10px;cursor:pointer">fermer</button>\n  </div>\n  <div id="triage-rows">chargement…</div>\n </div>\n</div>\n<script>\n// [TRIAGE-V1]\n(() => {\n  const CAT_COL = {\'LM fantome\':\'#e74c3c\',\'outlier isole\':\'#f59e0b\',\'markings a reviewer\':\'#c084fc\',\n                   \'erreur etalee\':\'#22d3ee\',\'sous-determinee\':\'#888\'};\n  const btn = document.getElementById(\'triage-btn\');\n  const modal = document.getElementById(\'triage-modal\');\n  const box = document.getElementById(\'triage-rows\');\n\n  async function load() {\n    box.textContent = \'analyse en cours…\';\n    const d = await fetch(\'/api/triage\').then(r => r.json());\n    document.getElementById(\'triage-count\').textContent = d.n + \' cams > 5\\\'\';\n    box.innerHTML = \'\';\n    let lastCat = null;\n    for (const r of d.rows) {\n      if (r.categorie !== lastCat) {\n        lastCat = r.categorie;\n        const h = document.createElement(\'div\');\n        h.style.cssText = \'margin:12px 0 4px;font-weight:700;color:\' + (CAT_COL[r.categorie] || \'#ccc\');\n        h.textContent = r.categorie.toUpperCase();\n        box.appendChild(h);\n      }\n      const row = document.createElement(\'div\');\n      row.style.cssText = \'display:flex;gap:10px;align-items:center;padding:5px 6px;border-radius:5px;border-bottom:1px solid #ffffff0e\';\n      const gain = r.gain_estime ? \' <span style="color:#2ecc71">−\' + r.gain_estime + \'\\\'</span>\' : \'\';\n      row.innerHTML = \'<a href="#" data-cam="\' + r.cam.replace(/"/g,\'&quot;\') + \'" class="tr-cam" \' +\n        \'style="color:var(--text,#ddd);min-width:220px;text-decoration:none">\' + r.cam + \'</a>\' +\n        \'<span style="color:\' + (CAT_COL[r.categorie]||\'#ccc\') + \';min-width:52px">\' + r.rms + "\'" + \'</span>\' +\n        \'<span style="flex:1;color:var(--mid,#999)">\' + r.detail + gain + \'</span>\';\n      const act = document.createElement(\'button\');\n      act.style.cssText = \'background:#ffffff14;border:1px solid var(--border,#333);color:var(--text,#ddd);\' +\n                          \'border-radius:5px;padding:3px 9px;cursor:pointer;white-space:nowrap\';\n      act.textContent = r.action;\n      act.addEventListener(\'click\', async () => {\n        if (r.categorie === \'outlier isole\') {\n          if (!confirm(\'Exclure le marking "\' + r.worst_lm + \'" sur \' + r.cam + \' ?\')) return;\n          const res = await fetch(\'/api/exclude_marking?cam=\' + encodeURIComponent(r.cam) +\n                                  \'&lm=\' + encodeURIComponent(r.worst_lm)).then(x => x.json());\n          if (res.ok) load();\n        } else if (r.categorie === \'LM fantome\') {\n          if (!confirm(\'Quarantaine (null xyz) de "\' + r.worst_lm + \'" ? Les markings restent dans pixels.json.\')) return;\n          const res = await fetch(\'/api/quarantine_lm?lm=\' + encodeURIComponent(r.worst_lm)).then(x => x.json());\n          if (res.ok) load(); else alert(res.error || \'erreur\');\n        } else {\n          selectCamByName(r.cam);\n          modal.style.display = \'none\';\n        }\n      });\n      row.appendChild(act);\n      row.querySelector(\'.tr-cam\').addEventListener(\'click\', e => {\n        e.preventDefault();\n        selectCamByName(r.cam);\n        modal.style.display = \'none\';\n      });\n      box.appendChild(row);\n    }\n  }\n\n  function selectCamByName(name) {\n    const sel = document.getElementById(\'cam-sel\') || document.querySelector(\'select\');\n    if (!sel) return;\n    for (const o of sel.options) if (o.value === name || o.value.includes(name)) { sel.value = o.value; break; }\n    sel.dispatchEvent(new Event(\'change\'));\n  }\n\n  if (btn) btn.addEventListener(\'click\', () => { modal.style.display = \'block\'; load(); });\n  modal.addEventListener(\'click\', e => { if (e.target === modal) modal.style.display = \'none\'; });\n})();\n</script>\n'
assert '</body>' in s
s = s.replace('</body>', block + '</body>', 1)
open(P, 'w').write(s)
print('TRIAGE-V1 client patche. Backup: .bak_triage')
